+</h1>
+
+@if (_notifications.Count == 0)
+{
+    <p><em>No notifications yet.</em></p>
+}
+else
+{
+    <ul class="list-group">
+        @foreach (var item in _notifications)
+        {
+            <li class="list-group-item d-flex justify-content-between align-items-start">
+                <span>@item.Message</span>
+                <small class="text-muted">@item.Timestamp.ToString("HH:mm:ss")</small>
+            </li>
+        }
+    </ul>
+}
+
+@code {
+    private List<NotificationItem> _notifications = new();
+    private CancellationTokenSource? _cts;
+
+    // Runs during SSR *and* when the component re-initializes interactively.
+    // PersistentComponentState is overkill here — we simply store the list in a
+    // field so OnAfterRenderAsync can skip re-fetching.
+    protected override async Task OnInitializedAsync()
+    {
+        _notifications = await NotificationService.GetInitialNotificationsAsync();
+    }
+
+    // Only called once the component is live in the browser (never during SSR).
+    protected override void OnAfterRender(bool firstRender)
+    {
+        if (firstRender)
+        {
+            _cts = new CancellationTokenSource();
+            _ = PollForNotificationsAsync(_cts.Token);
+        }
+    }
+
+    private async Task PollForNotificationsAsync(CancellationToken ct)
+    {
+        while (!ct.IsCancellationRequested)
+        {
+            await Task.Delay(TimeSpan.FromSeconds(5), ct);
+
+            var newItems = await NotificationService.CheckForNewNotificationsAsync();
+            if (newItems.Count > 0)
+            {
+                _notifications.InsertRange(0, newItems);
+                await InvokeAsync(StateHasChanged);
+            }
+        }
+    }
+
+    public void Dispose()
+    {
+        _cts?.Cancel();
+        _cts?.Dispose();
+    }
+}
